<script lang="ts">
  import { game } from '../../../gameManager.js';

  interface Props {
    title: string;
    tooltip: string;
    tag?: 'h3' | 'h4';
    id?: string;
    class?: string;
  }

  let { title, tooltip, tag = 'h4', id, class: className = '' }: Props = $props();

  function showTooltip(e: MouseEvent): void {
    if (!tooltip || !game?.scheduleTooltip) return;
    const html = tooltip.replace(/\n/g, '<br>');
    game.scheduleTooltip(e, '', html, 50);
  }

  function hideTooltip(): void {
    game?.hideTooltip?.();
  }
</script>

<svelte:element
  this={tag}
  {id}
  class="{className} tr-section-heading-with-hint"
>
  <span class="tr-section-heading-text">{title}</span>
  <button
    type="button"
    class="tr-section-tooltip-hint"
    aria-label="?"
    onmouseenter={showTooltip}
    onmouseleave={hideTooltip}
    onfocus={showTooltip}
    onblur={hideTooltip}
  >?</button>
</svelte:element>
