<script lang="ts">
  /* eslint-disable svelte/no-at-html-tags -- item icons from snapshot */
  import { rocket } from '../../stores/rocket.svelte.ts';
  import type { RocketStakingSessionSnapshot } from '../../bus/snapshots.js';
  import RocketSectionHeading from './RocketSectionHeading.svelte';

  let staking = $derived(rocket.snapshot.staking);
  let rt = $derived(rocket.realtime);
  let timerText = $derived(rt.stakingTimerText || staking.timerText);
  let session = $derived(
    staking.session
      ? ((rt.session ?? staking.session) as RocketStakingSessionSnapshot)
      : null,
  );
  let stakingTooltip = $derived(
    session ? timerText : `${timerText}\n${staking.noSessionText}`,
  );
</script>

<RocketSectionHeading
  id="rocketStakingSectionTitle"
  class="tr-section-title tr-section-title-standalone tr-text-title"
  title={staking.sectionTitle}
  tooltip={stakingTooltip}
/>

{#if staking.stealFeedback}
  <div class="shop-item rocket-steal-feedback">
    <div class="tr-text-title">{staking.stealFeedback.title}</div>
    <div class="tr-text-body">{staking.stealFeedback.body}</div>
    <div class="tr-text-status tr-text-status--danger">{staking.stealFeedback.lossText}</div>
    <button
      class="shop-buy-btn"
      style="background:#7f1d1d;"
      data-action="handleRocketDismissStealFeedback"
    >{staking.stealFeedback.acknowledgeButton}</button>
  </div>
{/if}

<div id="rocketStakingMount">
  <div class="team-rocket-grid" style="margin-bottom:8px;">
    {#if session}
      <div class="shop-item" class:rocket-risk-shake={session.isHighRisk}>
        <div class="tr-text-title">{session.sessionTitle}</div>
        <div class="tr-text-body" id="rocketPushSessionItemText">
          {session.objectLine}
        </div>
        <div class="rocket-push-live-wrap">
          <div
            id="rocketPushTimerCircle"
            class="rocket-push-timer-circle"
            style="--progress:{session.progressPct.toFixed(2)};"
          >
            <div id="rocketPushTimerText" class="tr-text-value tr-text-value--sm">{session.timerText}</div>
          </div>
          <div style="flex:1; min-width:0;">
            <div class="tr-text-value" id="rocketPushRjLive">{session.accumulatedText}</div>
            <div class="tr-text-body" id="rocketPushGpsLive">{session.gpsText}</div>
            <div
              id="rocketPushRiskLive"
              class="tr-text-status"
              class:tr-text-status--danger={session.riskVariant === 'danger'}
              class:tr-text-status--warn={session.riskVariant === 'warn'}
            >{session.riskText}</div>
            {#if session.nextTierHint}
              <div class="tr-text-muted tr-text-muted--italic tr-next-tier-hint" id="rocketPushNextTierHint">{session.nextTierHint}</div>
            {/if}
          </div>
        </div>
        <button type="button" class="tr-preset-btn tr-stake-btn" data-action="handleRocketRecoverStake">{session.recoverButton}</button>
      </div>
    {/if}
  </div>

  <div class="team-rocket-grid">
    {#each staking.stakeableItems as item (item.key)}
      <div class="shop-item tr-stake-card" class:not-affordable={!item.canStake}>
        <div class="tr-stake-icon">{@html item.iconHtml}</div>
        <div class="tr-stake-head">
          <div class="tr-text-title tr-stake-name">{item.displayName}</div>
          <span class="tr-stake-rate-pill">+{item.baseGpsFormatted} RJ/s</span>
        </div>
        <div class="tr-stake-meta tr-text-muted">
          <span class="tr-stake-category">{item.categoryLabel}</span>
          <span class="tr-stake-meta-sep" aria-hidden="true">·</span>
          <span class="tr-stake-owned">{item.ownedLine}</span>
        </div>
        <button
          type="button"
          class="tr-preset-btn tr-stake-btn"
          data-action="handleRocketStartContract"
          data-arg={item.key}
          disabled={!item.canStake}
        >{item.stakeButton}</button>
      </div>
    {:else}
      {#if staking.emptyMessage}
        <p class="tr-text-muted">{staking.emptyMessage}</p>
      {/if}
    {/each}
  </div>
</div>
